args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?maxDeath WHERE {
  VALUES ?film { <http://dbpedia.org/resource/Lost_in_the_Stratosphere> <http://dbpedia.org/resource/Blind_Man's_Eyes> }

  OPTIONAL {
    SELECT ?film (MAX(?deathDate) AS ?maxDeath) WHERE {
      ?film dbo:director ?dir .
      ?dir (dbo:deathDate|dbp:deathDate) ?deathDate .
    } GROUP BY ?film
  }

  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = 'en') }
}
ORDER BY DESC(?maxDeath)
LIMIT 1

